"""A tiny pure-functional text-adventure engine.

step(state, command) -> (new_state, output_text)

The state is never mutated; every command returns a fresh State.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field, replace


# --------------------------------------------------------------------------
# World definition
# --------------------------------------------------------------------------

ROOMS = {
    "cellar": {
        "name": "the cellar",
        "desc": "You are in a damp, dark cellar.",
        "exits": {"up": "hall"},
        "dark": True,
    },
    "hall": {
        "name": "the hall",
        "desc": "You are in a dusty hall. Doorways lead down and east.",
        "exits": {"down": "cellar", "east": "study"},
        "dark": False,
    },
    "study": {
        "name": "the study",
        "desc": "You are in a wood-panelled study.",
        "exits": {"west": "hall", "north": "vault"},
        "dark": False,
    },
    "vault": {
        "name": "the vault",
        "desc": "You are inside the vault, piles of gold all around!",
        "exits": {"south": "study"},
        "dark": False,
    },
}

# Items with their initial locations (None = nowhere / special).
ITEM_LOCATIONS = {
    "lantern": "hall",
    "key": "cellar",
}

LOCKED_EXITS = {("study", "north"): True}  # locked until key is used


@dataclass(frozen=True)
class State:
    room: str = "hall"
    items: dict = field(default_factory=lambda: dict(ITEM_LOCATIONS))
    inventory: frozenset = frozenset()
    unlocked: frozenset = frozenset()  # exit keys like ("study", "north")
    won: bool = False


# --------------------------------------------------------------------------
# Helpers
# --------------------------------------------------------------------------

def _can_see(state: State) -> bool:
    """The cellar is dark; you can only see while carrying the lantern."""
    return not ROOMS[state.room]["dark"] or "lantern" in state.inventory


def _describe_room(state: State) -> str:
    room = ROOMS[state.room]
    lines = [room["desc"]]
    here = [name for name, loc in state.items.items() if loc == state.room]
    if here:
        lines.append("You see: " + ", ".join(here) + ".")
    else:
        lines.append("There is nothing of interest here.")
    lines.append("Exits: " + ", ".join(sorted(room["exits"])) + ".")
    return "\n".join(lines)


def _locked(state: State, direction: str) -> bool:
    return LOCKED_EXITS.get((state.room, direction), False) and (
        state.room,
        direction,
    ) not in state.unlocked


# --------------------------------------------------------------------------
# The pure step function
# --------------------------------------------------------------------------

def step(state: State, command: str) -> tuple[State, str]:
    """Apply one command to the state, returning (new_state, output)."""
    words = command.strip().lower().split()
    if not words:
        return state, "Please enter a command."
    verb, args = words[0], words[1:]

    # ---------------- look ----------------
    if verb == "look":
        return state, (_describe_room(state) if _can_see(state)
                       else "It is pitch black. You need a light source.")

    # ---------------- inventory ----------------
    if verb == "inventory":
        if state.inventory:
            return state, "You are carrying: " + ", ".join(
                sorted(state.inventory)) + "."
        return state, "You are empty-handed."

    # ---------------- go <direction> ----------------
    if verb == "go":
        if not args:
            return state, "Go where?"
        direction = args[0]
        exits = ROOMS[state.room]["exits"]
        if direction not in exits:
            return state, f"You can't go '{direction}' from here."
        if _locked(state, direction):
            return state, "The door is locked. It needs a key."
        new_state = replace(state, room=exits[direction])
        if exits[direction] == "vault":
            new_state = replace(new_state, won=True)
            return new_state, "You step into the vault. Victory is yours!"
        out = f"You go {direction}.\n" + (
            _describe_room(new_state) if _can_see(new_state)
            else "It is pitch black. You need a light source.")
        return new_state, out

    # ---------------- take <item> ----------------
    if verb == "take":
        if not args:
            return state, "Take what?"
        item = args[0]
        if item not in state.items:
            return state, f"There is no '{item}' here."
        if state.items[item] != state.room or not _can_see(state):
            return state, f"You don't see any {item} here."
        new_items = dict(state.items)
        del new_items[item]
        new_state = replace(state, items=new_items,
                            inventory=state.inventory | {item})
        return new_state, f"You take the {item}."

    # ---------------- drop <item> ----------------
    if verb == "drop":
        if not args or args[0] not in state.inventory:
            return state, "You aren't carrying that."
        item = args[0]
        new_items = dict(state.items)
        new_items[item] = state.room
        new_state = replace(state, items=new_items,
                            inventory=state.inventory - {item})
        return new_state, f"You drop the {item}."

    # ---------------- use <item> ----------------
    if verb == "use":
        if not args:
            return state, "Use what?"
        item = args[0]
        if item == "key" and "key" in state.inventory:
            if _locked(state, "north") or any(
                    k for k in LOCKED_EXITS
                    if k[0] == state.room and k not in state.unlocked):
                new_state = replace(
                    state,
                    unlocked=state.unlocked | {
                        k for k in LOCKED_EXITS if k[0] == state.room
                    },
                )
                return new_state, "You unlock the door with the key."
            return state, "There is nothing here to unlock."
        if item == "lantern" and "lantern" in state.inventory:
            return state, "The lantern glows brightly."
        return state, "You can't use that."

    return state, f"I don't know how to '{verb}'."

